describe('dashboard mutation refresh', () => {
  it('revalidates after removal and renders the updated member list', async () => {
    expect(renderToStaticMarkup(<Page />)).toContain('Removal target');
    const form = new FormData();
    form.set('memberId', '2');
    ui.remove.mockResolvedValue({ success: 'Team member removed successfully' });
    ui.mutate.mockImplementation(async () => {
      const updated = makeTeam();
      updated.teamMembers = updated.teamMembers.filter((member) => member.id !== 2);
      ui.cache.set('/api/team', updated);
      return updated;
    });

    expect(await ui.reducers[0]({}, form)).toHaveProperty('success');
    expect(ui.remove).toHaveBeenCalledWith({}, form);
    expect(ui.mutate).toHaveBeenCalledExactlyOnceWith();
    expect(ui.remove.mock.invocationCallOrder[0]).toBeLessThan(ui.mutate.mock.invocationCallOrder[0]);
    expect(renderToStaticMarkup(<Page />)).not.toContain('Removal target');
  });

  it('revalidates every successful invitation, including repeated success messages', async () => {
    renderToStaticMarkup(<Page />);
    const invite = ui.reducers[1];
    const form = new FormData();
    form.set('email', 'new@fixture.invalid');
    form.set('role', 'member');
    const success = { success: 'Invitation sent successfully' };
    ui.invite.mockResolvedValue(success);
    ui.mutate.mockResolvedValue(makeTeam());

    expect(await invite({}, form)).toEqual(success);
    form.set('email', 'another@fixture.invalid');
    expect(await invite(success, form)).toEqual(success);
    expect(ui.invite).toHaveBeenCalledTimes(2);
    expect(ui.mutate).toHaveBeenCalledTimes(2);
    expect(ui.invite.mock.invocationCallOrder[0]).toBeLessThan(ui.mutate.mock.invocationCallOrder[0]);
  });

  it.each([0, 1])('does not refresh after rejected form action %i', async (index) => {
    const before = renderToStaticMarkup(<Page />);
    const error = { error: 'You must be a team owner.' };
    ui.remove.mockResolvedValue(error);
    ui.invite.mockResolvedValue(error);

    expect(await ui.reducers[index]({}, new FormData())).toEqual(error);
    expect(ui.mutate).not.toHaveBeenCalled();
    expect(renderToStaticMarkup(<Page />)).toEqual(before);
  });

  it.each(['/api/user', '/api/team'])('disables mutation controls while %s is unavailable', (key) => {
    ui.cache.delete(key);
    const html = renderToStaticMarkup(<Page />);
    expect(html.match(/<input\b[^>]*\bname="email"[^>]*>/)?.[0]).toMatch(/\bdisabled/);
    expect(html).toContain('team owner to invite new members');
    const buttons = [...html.matchAll(/<button\b([^>]*)>Remove<\/button>/g)];
    expect(buttons.every((button) => /\bdisabled/.test(button[1]))).toBe(true);
  });
});

