describe('team membership regression cases', () => {
  it.each([
    undefined, '', ' ', '0', '-1', '+3', '03', '3.0', '3.5', '3e0', '0x3',
    '3abc', ' 3', '3 ', '3\n', 'NaN', 'Infinity', '2147483648', '9007199254740993'
  ])('rejects invalid member ID %j without writes', async (value) => {
    const before = await snapshot();
    expect(await remove(value)).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
  });

  it('rejects a file in place of the member ID', async () => {
    const before = await snapshot();
    expect(await remove(new Blob(['3']))).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
  });

  it.each(['999', '4'])('rejects absent or other-team member %s without audit writes', async (id) => {
    const before = await snapshot();
    expect(await remove(id)).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
  });

  it('removes a member in the second list position and returns an updated team', async () => {
    expect(await remove('2')).toHaveProperty('success');
    const team = await (await GET()).json();
    expect(team.teamMembers.map((member: { id: number }) => member.id).sort()).toEqual([1, 3]);
    expect((await sql.query('SELECT id FROM team_members WHERE id=4')).rows).toEqual([{ id: 4 }]);
  });

  it('enables owner removal in every list position', async () => {
    const buttons = [...(await markup()).matchAll(/<button\b([^>]*)>Remove<\/button>/g)];
    expect(buttons).toHaveLength(3);
    expect(buttons.every((button) => !/\bdisabled(?:=|\s|$)/.test(button[1]))).toBe(true);
  });

  it('uses the first membership after its SQL row has been updated', async () => {
    // Updating a row can change physical scan order; it must not select the later owner membership.
    await sql.exec("UPDATE team_members SET role='member' WHERE id=2");
    await login(2);
    expect((await queries.getCurrentTeamMembership(2))?.id).toBe(2);
    expect((await queries.getTeamForUser())?.id).toBe(1);
    expect((await (await GET()).json()).id).toBe(1);
    const before = await snapshot();
    expect(await invite()).toHaveProperty('error');
    expect(await remove('3')).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
    const html = await markup();
    expect(html).toMatch(/team owner to remove members/);
    expect(html).toMatch(/team owner to invite new members/);
    const buttons = [...html.matchAll(/<button\b([^>]*)>Remove<\/button>/g)];
    expect(buttons).toHaveLength(3);
    expect(buttons.every((button) => /\bdisabled(?:=|\s|$)/.test(button[1]))).toBe(true);
  });

  it('rechecks the current role on direct calls after an owner is demoted', async () => {
    await sql.exec("UPDATE team_members SET role='member' WHERE id=1");
    const before = await snapshot();
    expect(await invite()).toHaveProperty('error');
    expect(await remove('3')).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
  });

  it.each(['member', 'owner'])('invites the requested %s role into the current team', async (role) => {
    expect(await invite('new@fixture.invalid', role)).toHaveProperty('success');
    expect((await sql.query('SELECT team_id,role,invited_by,status FROM invitations')).rows)
      .toEqual([{ team_id: 1, role, invited_by: 1, status: 'pending' }]);
    expect((await sql.query('SELECT team_id,action FROM activity_logs')).rows)
      .toEqual([{ team_id: 1, action: 'INVITE_TEAM_MEMBER' }]);
  });

  it('keeps duplicate invitations and existing members rejected', async () => {
    expect(await invite()).toHaveProperty('success');
    const before = await snapshot();
    expect(await invite()).toHaveProperty('error');
    expect(await invite('member@fixture.invalid')).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
  });

  it.each([['not-an-email', 'member'], ['new@fixture.invalid', 'admin']])(
    'rejects invalid invitation %s / %s without writes', async (email, role) => {
      const before = await snapshot();
      expect(await invite(email, role)).toHaveProperty('error');
      expect(await snapshot()).toEqual(before);
    }
  );

  it('denies actions for an authenticated user without a membership', async () => {
    await login(4);
    const before = await snapshot();
    expect(await queries.getTeamForUser()).toBeNull();
    expect(await invite()).toHaveProperty('error');
    expect(await remove('3')).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
  });

  it.each(['missing', 'expired', 'deleted'])(
    'rejects a %s session at the API and both actions without writes', async (kind) => {
      if (kind === 'missing') request.token = '';
      if (kind === 'expired') await login(1, Date.now() - 60000);
      if (kind === 'deleted') await sql.exec('UPDATE users SET deleted_at=NOW() WHERE id=1');
      const before = await snapshot();
      const response = await GET();
      expect(response.status).toBe(401);
      expect(await response.json()).toBeNull();
      await expect(invite()).rejects.toThrow('not authenticated');
      await expect(remove('3')).rejects.toThrow('not authenticated');
      expect(await snapshot()).toEqual(before);
    }
  );
});

